export const withAPI = (options) => (component) => {
    return {
        ...component,
        element: component.element,
        setValue(value, triggerEvent = false) {
            options.slider.setValue(value, triggerEvent);
            return this;
        },
        getValue() {
            return options.slider.getValue();
        },
        setSecondValue(value, triggerEvent = false) {
            options.slider.setSecondValue(value, triggerEvent);
            return this;
        },
        getSecondValue() {
            return options.slider.getSecondValue();
        },
        setMin(min) {
            options.slider.setMin(min);
            return this;
        },
        getMin() {
            return options.slider.getMin();
        },
        setMax(max) {
            options.slider.setMax(max);
            return this;
        },
        getMax() {
            return options.slider.getMax();
        },
        setStep(step) {
            options.slider.setStep(step);
            return this;
        },
        getStep() {
            return options.slider.getStep();
        },
        enable() {
            options.disabled.enable();
            return this;
        },
        disable() {
            options.disabled.disable();
            return this;
        },
        isDisabled() {
            return options.disabled.isDisabled();
        },
        setColor(color) {
            options.appearance.setColor(color);
            return this;
        },
        getColor() {
            return options.appearance.getColor();
        },
        setSize(size) {
            options.appearance.setSize(size);
            return this;
        },
        getSize() {
            return options.appearance.getSize();
        },
        showTicks(show) {
            options.appearance.showTicks(show);
            return this;
        },
        showCurrentValue(show) {
            options.appearance.showCurrentValue(show);
            return this;
        },
        setLabel(text) {
            if (options.text?.setText)
                options.text.setText(text);
            return this;
        },
        getLabel() {
            return options.text?.getText ? options.text.getText() : "";
        },
        setInsetIcon(icon, atMin) {
            options.insetIcon.setInsetIcon(icon, atMin);
            return this;
        },
        setIcon(iconHtml) {
            if (options.icon?.setIcon)
                options.icon.setIcon(iconHtml);
            return this;
        },
        getIcon() {
            return options.icon?.getIcon ? options.icon.getIcon() : "";
        },
        on(event, handler) {
            if (options.events?.on)
                options.events.on(event, handler);
            return this;
        },
        off(event, handler) {
            if (options.events?.off)
                options.events.off(event, handler);
            return this;
        },
        destroy() {
            if (options.lifecycle?.destroy)
                options.lifecycle.destroy();
        },
    };
};
